-- V44: Product 模块 — 演示商品/SKU 全量重建
-- 清空商品、SKU、库存主体与购物车后，插入覆盖各品类的高质量演示数据，规格/参数取值全部对齐 V43 类目模板
-- （attrId/valueId 与模板逐一对得上，specs/params/attributes 形状与 ProductService 口径一致）。
-- 演示店铺为固定 UUID（owner_id 是占位值，不指向真实用户）；图片沿用既有约定放 picsum 占位 URL
-- （imgUrl 对完整 URL 原样返回，开发环境未配 CDN 也能渲染）。
-- 订单数据保留不动（下单即快照，不引用 sku 行）；关联旧 sku_id 的购物车一并清空。

TRUNCATE product.products, product.skus, inventory.sku_stock, inventory.stock_movements, cart.items;

ON CONFLICT (id) DO NOTHING;



SELECT id, 40 + (abs(hashtext(id::text)) % 460)
FROM product.skus;
